class Solution {
public:
    int minimumK(vector<int>& nums) {
        int lo = 1, hi = max((int)nums.size(), *max_element(nums.begin(), nums.end()));
        auto feasible = [&](long long k) {
            long long limit = k * k, ops = 0;
            for (int v : nums) {
                ops += (v + k - 1) / k;
                if (ops > limit) return false;
            }
            return true;
        };
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (feasible(mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};
